import java.io.*;
import java.net.*;
import java.nio.file.*;

/**
 * Patched to disable AF_UNIX support, forcing PipeImpl to use TCP loopback.
 * Needed for environments where AF_UNIX connect() returns EINVAL.
 */
class UnixDomainSockets {
    static final UnixDomainSocketAddress UNNAMED;
    private static final boolean supported = false;

    static {
        UNNAMED = UnixDomainSocketAddress.of("");
    }

    private UnixDomainSockets() {}

    static boolean isSupported() {
        return false;
    }

    static void checkPermission() {}

    static UnixDomainSocketAddress getRevealedLocalAddress(SocketAddress sa) {
        if (sa instanceof UnixDomainSocketAddress)
            return (UnixDomainSocketAddress) sa;
        return null;
    }

    static UnixDomainSocketAddress localAddress(FileDescriptor fd) throws IOException {
        throw new UnsupportedOperationException("Unix domain sockets not supported");
    }

    static String getRevealedLocalAddressAsString(SocketAddress sa) {
        UnixDomainSocketAddress usa = getRevealedLocalAddress(sa);
        return usa == null ? null : usa.toString();
    }

    static UnixDomainSocketAddress checkAddress(SocketAddress sa) {
        if (sa instanceof UnixDomainSocketAddress)
            return (UnixDomainSocketAddress) sa;
        throw new IllegalArgumentException("Not a UnixDomainSocketAddress");
    }

    static byte[] getPathBytes(Path path) {
        return path.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);
    }

    static FileDescriptor socket() throws IOException {
        throw new IOException("Unix domain sockets not supported");
    }

    static void bind(FileDescriptor fd, Path path) throws IOException {
        throw new IOException("Unix domain sockets not supported");
    }

    static UnixDomainSocketAddress generateTempName() throws IOException {
        throw new IOException("Unix domain sockets not supported");
    }

    static int connect(FileDescriptor fd, SocketAddress sa) throws IOException {
        throw new IOException("Unix domain sockets not supported");
    }

    static int connect(FileDescriptor fd, Path path) throws IOException {
        throw new IOException("Unix domain sockets not supported");
    }

    static int accept(FileDescriptor fd, FileDescriptor newfd, String[] isaa) throws IOException {
        throw new IOException("Unix domain sockets not supported");
    }
}
